# Disable Multi-Plane Overlay (MPO) Write-Host "Disabling Multi-Plane Overlay (MPO)..." -ForegroundColor Cyan # Disable MPO via registry override $mpoKey = "HKLM:\SOFTWARE\Microsoft\Windows\Dwm" if (-not (Test-Path $mpoKey)) { New-Item -Path $mpoKey -Force | Out-Null } Set-ItemProperty -Path $mpoKey -Name "OverlayTestMode" -Value 5 -Type DWord -Force -ErrorAction Stop Write-Host "Multi-Plane Overlay (MPO) has been disabled." -ForegroundColor Green Write-Host "A restart may be required for changes to take effect." -ForegroundColor Yellow